<?php require_login();$data=cart_details();if(!$data['items']){flash('Your bag is empty.','warn');redirect('shop');}$user=auth();$_SESSION['checkout_quote']=order_quote($data['items'],cart());$fee=delivery_fee('cod',$data['subtotal']);?><section class="page-heading compact"><div class="container"><span class="eyebrow">THE LAST LITTLE STEP</span><h1>Secure <em>checkout.</em></h1></div></section><section class="container section"><div class="cart-layout"><form id="checkout-form" class="checkout-form" method="post" action="<?=h(url('checkout'))?>"><?=csrf_input()?><input type="hidden" name="action" value="checkout"><h2>Delivery details</h2><div class="field"><label for="customer-name">Full name</label><input id="customer-name" name="name" value="<?=h($user['name'])?>" maxlength="100" minlength="2" required></div><div class="field"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" maxlength="30" placeholder="+962 7X XXX XXXX" required></div><div class="field"><label for="address">Delivery address (required for delivery)</label><textarea id="address" name="address" maxlength="255" minlength="8" placeholder="City, neighborhood, street and building"></textarea></div><div class="field"><label for="note">Order note (optional)</label><textarea id="note" name="note" maxlength="500" placeholder="Anything we should know?"></textarea></div><h2>How would you like it?</h2><label class="radio-option"><input type="radio" name="payment_method" value="cod" checked> Cash on delivery <span>Pay on arrival</span></label><label class="radio-option"><input type="radio" name="payment_method" value="pickup"> Pickup in store <span>No delivery fee</span></label><p class="micro">Academic demo: No online card payments are processed.</p></form><aside class="summary-card" id="checkout-summary" data-subtotal="<?=intval(round(100*$data['subtotal']))?>" data-fee="<?=intval(round(100*$fee))?>"><h2>Your treats</h2><?php foreach($data['items'] as $item):?><div class="summary-line"><span><?=intval($item['qty'])?> × <?=h($item['name'])?></span><b><?=h(money($item['line_total']))?></b></div><?php endforeach;?><hr><div class="summary-line total"><span>Subtotal</span><strong><?=h(money($data['subtotal']))?></strong></div><div class="summary-line"><span>Delivery</span><strong id="checkout-fee"><?=h(money($fee))?></strong></div>
<div class="summary-line total"><span>Total</span><strong id="checkout-total" aria-live="polite"><?=h(money($data['subtotal']+$fee))?></strong></div>
<noscript><p class="micro">Pickup costs <?=h(money($data['subtotal']))?> in total.</p></noscript><button class="btn btn-primary full" type="submit" form="checkout-form">Confirm order ↗</button></aside></div></section>
